package com.dukaops.backend.sales; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID; import com.dukaops.backend.tenant.Tenant; import jakarta.persistence.*;
@Entity @Table(name="sales_payments") public class SalesPayment { @Id private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="tenant_id") private Tenant tenant; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="order_id") private SalesOrder order; @Enumerated(EnumType.STRING) private PaymentMethod method; private BigDecimal amount; private String reference; private Instant createdAt; protected SalesPayment(){} public SalesPayment(Tenant t,SalesOrder o,PaymentMethod m,BigDecimal a,String r){id=UUID.randomUUID();tenant=t;order=o;method=m;amount=a;reference=r;} @PrePersist void create(){createdAt=Instant.now();} }
